package dev.zomboidmelee.boxing;
import java.util.*;import net.minecraft.client.Minecraft;import net.minecraft.world.phys.Vec3;import net.minecraft.world.level.ClipContext;
public class ReticleChecks34{
 static int n;static void ok(boolean b,String s){n++;if(!b)throw new AssertionError(s);}static void near(double a,double b,String s){ok(Math.abs(a-b)<1e-5,s);}public record Stage(String getStage,LaserChecks32.Mat getModelViewMatrix,LaserChecks32.Mat getProjectionMatrix){}
 public static class Part{double[]matrix;Part(double[]m){matrix=m;}public void translateAndRotateAndScale(Object stack){var p=(LaserChecks32.Stack)stack;p.matrix=Matrix32.mul(p.matrix,matrix);}}
 public static class Scope{public List<List<Part>>divisionNodePaths;public Scope(Part p){divisionNodePaths=List.of(List.of(p));}public boolean isSight(){return true;}public boolean isScope(){return false;}}
 public static class Wall extends ParkourChecks25.World{double distance;Wall(double d){distance=d;}public LaserChecks32.Hit clip(ClipContext c){double z=-distance;if(c.from().z>z&&c.to().z<=z){double t=(z-c.from().z)/(c.to().z-c.from().z);return new LaserChecks32.Hit(new Vec3(c.from().x+(c.to().x-c.from().x)*t,c.from().y+(c.to().y-c.from().y)*t,z));}return new LaserChecks32.Hit(null);}}
 public static void main(String[]args){var mc=Minecraft.INSTANCE;var p=new LaserChecks32.Local();p.px=p.pz=0;p.py=-1.62;mc.player=p;mc.level=p.physics;mc.screen=null;mc.options.keyUse.down=true;var view=Matrix32.identity();var projection=Sight34.perspective(70,16d/9);Sight34.stage(new Stage("minecraft:after_level",new LaserChecks32.Mat(view),new LaserChecks32.Mat(projection)));Laser32.view=view;
 Sight34.begin();var pose=new LaserChecks32.Stack(Matrix32.identity());var scope=new Scope(new Part(LaserChecks32.transform(0,.08,.04,-1)));Sight34.capture(scope,pose,LaserChecks32.Context.FIRST_PERSON_RIGHT_HAND,null);ok(Sight34.reticle!=null&&pose.depth==0,"same-frame real sight path captured with balanced matrix");double x=Sight34.reticle[0],y=Sight34.reticle[1];for(double d:new double[]{1,5,25,80,150,250}){var w=new Wall(d);double[]hit=Sight34.aim(p,w,new double[]{.22,-.15,-.4},new double[]{0,0,0});ok(hit[2]>-d&&hit[2]<-d+.01,"world ray reaches distant surface, capped by that wall");for(double fov:new double[]{25,50,70,95}){double[]ip=Sight34.perspective(fov,16d/9),eye=Sight34.eyePoint(hit,new double[]{0,0,0},ip),ndc=Matrix32.point(ip,eye[0],eye[1],eye[2]);ok(Math.abs(ndc[0]-x)<.0008&&Math.abs(ndc[1]-y)<.0008,"laser point coincides with optical reticle across FOV and distance");ok(eye[2]>=-8&&eye[2]<=-.31,"distant first-person beam remains within hand-render clipping range");double radius=Sight34.radius(eye[2],1.35,.0015,1080,ip[5]),pixels=radius*ip[5]*1080/(2*-eye[2]);ok(pixels>=1.349&&pixels<=4.001,"distant dot stays visible without becoming a large square");}}
 boolean[]emitted={false};Sight34.pending.add(()->{emitted[0]=Sight34.reticle!=null;});Sight34.end();ok(emitted[0]&&Sight34.pending.isEmpty()&&Sight34.reticle==null,"pending laser sees same-frame optic before frame is cleared");
 Sight34.begin();mc.level=new Wall(100);var camera=new LaserChecks32.Camera(p,new Vec3(0,0,0));mc.gameRenderer=new LaserChecks32.Renderer(camera);var buffers=new LaserChecks32.Buffers();mc.renderBuffer=buffers;Laser32.world=mc.level;var laserPose=new LaserChecks32.Stack(LaserChecks32.transform(0,.2,-.2,-.4));ok(Laser32.render(new Object(),laserPose,LaserChecks32.Context.FIRST_PERSON_RIGHT_HAND,List.of()),"real first-person entry queues calibrated beam");ok(buffers.v.points.isEmpty(),"laser waits when attachment draws before optic");Sight34.capture(scope,pose,LaserChecks32.Context.FIRST_PERSON_RIGHT_HAND,null);Sight34.end();ok(buffers.v.points.size()==12&&buffers.flushed==1,"queued beam emits and flushes after reticle becomes available");var dot=buffers.v.points.subList(8,12);double cx=dot.stream().mapToDouble(v->v[0]).average().orElseThrow(),cy=dot.stream().mapToDouble(v->v[1]).average().orElseThrow(),cz=dot.get(0)[2];var actual=Matrix32.point(projection,cx,cy,cz);ok(Math.abs(actual[0]-x)<.0001&&Math.abs(actual[1]-y)<.0001,"actual emitted dot vertices, not just a helper ray, align with same-frame sight");ok(buffers.v.colors.contains(0xFF0000)&&buffers.v.alpha.stream().allMatch(a->a==251),"reticle/distance fix retains hue and Darkness/NVG emission stamp");
 var bad=new LaserChecks32.Vertices();Sight34.drawEye(bad,view,projection,new double[]{0,0,.5},new double[]{0,0,1},.004,0xFF0000,true,1080);ok(bad.points.isEmpty(),"reticle renderer does not reintroduce behind-camera triangles");System.out.println("SAME_FRAME_OPTICAL_RETICLE_250M_FOV_PIXEL_SIZE_DEFERRED_EMISSION_CHECKS="+n);}
}
